const TOP = 20;

// Collect real FAQ rows (skip blanks) keeping their sheet row number.
// First data row is 2 (header on row 1).
const rows = [];
const all = $('Read FAQ').all();
for (let i = 0; i < all.length; i++) {
  const j = all[i].json || {};
  if (!j || !j.question) continue;
  rows.push({
    sheetRow: i + 2,
    question: String(j.question),
    hit_count: Number(j.hit_count || 0) || 0,
  });
}

// Sort most-asked first (ties: keep existing order = stable).
rows.sort(function (a, b) { return b.hit_count - a.hit_count; });

const keep = rows.slice(0, TOP);   // top 20 -> re-number rank 1..N
const drop = rows.slice(TOP);      // tail -> delete from sheet

// Emit control rows on json so downstream branches can act.
const out = [];

// (1) Rank updates for kept rows (appendOrUpdate by question).
for (let i = 0; i < keep.length; i++) {
  out.push({ json: {
    kind: 'rank',
    question: keep[i].question,
    hit_count: keep[i].hit_count,
    rank: i + 1,
  } });
}

// (2) Delete ranges for dropped rows, DESCENDING so earlier deletes don't
// shift the indexes of ranges not yet deleted. Merge contiguous rows.
const dropRowNums = drop.map(function (r) { return r.sheetRow; }).sort(function (a, b) { return a - b; });
const ranges = [];
let start = null, prev = null;
for (const r of dropRowNums) {
  if (start === null) { start = r; prev = r; }
  else if (r === prev + 1) { prev = r; }
  else { ranges.push({ startIndex: start, numberToDelete: prev - start + 1 }); start = r; prev = r; }
}
if (start !== null) ranges.push({ startIndex: start, numberToDelete: prev - start + 1 });
ranges.sort(function (a, b) { return b.startIndex - a.startIndex; });
for (const rg of ranges) {
  out.push({ json: { kind: 'delete', startIndex: rg.startIndex, numberToDelete: rg.numberToDelete } });
}

return out;

// One-time seed of the project's most-asked Q&A. Edit / extend this list with
// your real top questions before running. hit_count sets the initial ranking.
// Answers are short cached replies; on a FAQ hit 04 serves these verbatim with
// ZERO Gemini chat calls. Keep answers concise and LINE-friendly.
const seed = [
  { question: 'SuperChoice AI คืออะไร', answer: 'SuperChoice AI คือระบบ AI RAG อัตโนมัติแบบครบวงจร พร้อมการจัดการวงจรชีวิตข้อมูล (backup, error log, cleanup) ตอบคำถามจากคลังความรู้ YouTube + เอกสาร ผ่าน LINE OA และ Web Chat', hit_count: 20 },
  { question: 'ระบบใช้เทคโนโลยีอะไรบ้าง', answer: 'ใช้ n8n เป็น orchestrator, Gemini embedding (gemini-embedding-001, 1536 มิติ) + gemini-2.5-flash, Supabase pgvector สำหรับค้นความคล้าย, Supadata สำหรับถอดเสียง YouTube และ Google Sheets เป็น control plane', hit_count: 18 },
  { question: 'รองรับภาษาอะไร', answer: 'ระบบตอบเป็นภาษาเดียวกับคำถามอัตโนมัติ (เช่น ถามไทยตอบไทย ถามอังกฤษตอบอังกฤษ)', hit_count: 15 },
  { question: 'เชื่อมต่อกับ LINE OA ได้ไหม', answer: 'ได้ครับ ระบบรองรับทั้ง LINE OA และ Web Chat โดยตอบกลับในช่องทางเดิมที่ผู้ใช้ถามเข้ามา', hit_count: 12 },
];
return seed.map(function (s) { return { json: { question: s.question, answer: s.answer, hit_count: s.hit_count } }; });

// Runs ONCE for all items. Embed Seed splits into one output item per seed
// row (paired by index with Seed FAQ Rows). Iterate ALL items — reading only
// $input.first() would collapse every seed to a single row.
const seeds = $('Seed FAQ Rows').all();
const inputs = $input.all();

const rows = [];
for (let i = 0; i < inputs.length; i++) {
  const emb = (((inputs[i].json || {}).embedding) || {}).values || [];
  const q = ((seeds[i] || {}).json) || {};
  if (!q.question) continue;
  rows.push({
    question: q.question,
    answer: q.answer || '',
    hit_count: Number(q.hit_count || 0) || 0,
    embedding: JSON.stringify(emb),
    // Seed rows are hand-curated, so they are approved and usable immediately.
    approved: true,
    updated_at: new Date().toISOString(),
  });
}

// Assign rank immediately by hit_count DESC (principle 3.1). The daily
// re-rank (Path A) keeps this in sync afterwards.
rows.sort(function (a, b) { return b.hit_count - a.hit_count; });
return rows.map(function (r, i) {
  return { json: {
    question: r.question,
    answer: r.answer,
    hit_count: r.hit_count,
    embedding: r.embedding,
    rank: i + 1,
    approved: r.approved,
    updated_at: r.updated_at,
  } };
});
